def build_plan():
    plan = []

    # Single large neighborhood centered at (60, 50) with horizontal spine
    # Power plant at top, horizontal wire spine, roads running N-S

    cx, cy = 60, 50

    # Two coal plants for redundant power
    plan.append((Tool.COALPOWER, cx - 20, cy - 15))
    plan.append((Tool.COALPOWER, cx + 20, cy - 15))

    # Horizontal wire spine at cy - 15 connecting the two plants
    for x in range(cx - 19, cx + 20):
        plan.append((Tool.WIRE, x, cy - 15))

    # Vertical wire columns dropping down from spine to power zones
    # Three vertical wire columns at x = cx-12, cx, cx+12
    for col in [cx - 12, cx, cx + 12]:
        for dy in range(-15, 18):
            plan.append((Tool.WIRE, col, cy + dy))

    # Horizontal roads every 3 rows for zone access
    for ry in range(cy - 12, cy + 16, 3):
        for x in range(cx - 18, cx + 19):
            plan.append((Tool.ROAD, x, ry))

    # Vertical roads at regular intervals to connect horizontal roads
    for rx in range(cx - 18, cx + 19, 3):
        for dy in range(-12, 16):
            plan.append((Tool.ROAD, rx, cy + dy))

    # Place zones in a grid pattern
    # Columns: residential left, mix in center, industrial right
    for row in range(cy - 9, cy + 13, 3):
        for col in range(cx - 15, cx - 6, 3):
            plan.append((Tool.RESIDENTIAL, col, row))
        for col in range(cx - 6, cx + 7, 3):
            plan.append((Tool.COMMERCIAL, col, row))
        for col in range(cx + 7, cx + 16, 3):
            plan.append((Tool.INDUSTRIAL, col, row))

    # Add wire under zones that are near wire columns to ensure power
    # Re-lay wires on the spine columns after zones (zones overwrite wires)
    for col in [cx - 12, cx, cx + 12]:
        for dy in range(-14, 18):
            plan.append((Tool.WIRE, col, cy + dy))

    # Also re-lay horizontal wire spine
    for x in range(cx - 20, cx + 21):
        plan.append((Tool.WIRE, x, cy - 15))

    # Services
    plan.append((Tool.FIRESTATION, cx - 18, cy - 6))
    plan.append((Tool.FIRESTATION, cx + 15, cy - 6))
    plan.append((Tool.POLICESTATION, cx - 18, cy + 6))
    plan.append((Tool.POLICESTATION, cx + 15, cy + 6))

    # Stadium for commercial boost
    plan.append((Tool.STADIUM, cx, cy + 18))

    # Connect wire from spine down to center of zone grid
    for x in range(cx - 20, cx + 21):
        plan.append((Tool.WIRE, x, cy - 14))

    return plan


def act(obs, state):
    if "plan" not in state:
        state["plan"] = build_plan()
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]

    if i >= len(plan):
        return None

    state["i"] = i + 1
    tool, x, y = plan[i]

    # Clamp coordinates to valid range
    x = max(0, min(WORLD_W - 1, x))
    y = max(0, min(WORLD_H - 1, y))

    return (tool, x, y)

def build_plan():
    plan = []

    # Strategy: Grid-based city with proper power connectivity
    # Use a horizontal wire backbone connecting all power plants
    # Zones arranged in rows with roads between them
    # Mix of R, C, I zones for diversity

    # Power plants positioned first, then wire backbone, then zones

    # We'll build 4 horizontal strips, each with:
    # - Road lane
    # - Wire lane  
    # - Alternating R/C/I zones above and below

    # Main parameters
    strip_ys = [20, 38, 56, 74]  # y centers of road/wire lanes
    plant_xs = [10, 50, 90]       # x positions of coal plants

    # Place coal plants at various positions
    for px in plant_xs:
        for sy in strip_ys[0:2]:
            plan.append((Tool.COALPOWER, px, sy - 3))
        for sy in strip_ys[2:4]:
            plan.append((Tool.COALPOWER, px, sy + 3))

    # Horizontal wire backbone along each strip
    for sy in strip_ys:
        for x in range(2, WORLD_W - 2):
            plan.append((Tool.WIRE, x, sy))
        for x in range(2, WORLD_W - 2):
            plan.append((Tool.ROAD, x, sy + 1))

    # Vertical wire connections between strips
    for vx in [10, 30, 50, 70, 90, 110]:
        for y in range(strip_ys[0], strip_ys[-1] + 1):
            plan.append((Tool.WIRE, vx, y))

    # Vertical roads between strips
    for vx in [12, 32, 52, 72, 92]:
        for y in range(strip_ys[0], strip_ys[-1] + 2):
            plan.append((Tool.ROAD, vx, y))

    # Place zones between roads
    # Zone columns (centers), avoiding wire/road lanes
    # Each strip has road at sy+1, wire at sy
    # Place zones above the wire (at sy-3, sy-6) and below road (at sy+4, sy+7)

    zone_xs = list(range(15, WORLD_W - 5, 6))  # zone centers every 6 tiles

    for i, sy in enumerate(strip_ys):
        for j, zx in enumerate(zone_xs):
            # Alternate zone types: R, C, I based on position
            zone_type_idx = (i + j) % 3
            if zone_type_idx == 0:
                zt = Tool.RESIDENTIAL
            elif zone_type_idx == 1:
                zt = Tool.COMMERCIAL
            else:
                zt = Tool.INDUSTRIAL

            # Zone above wire lane
            zy_above = sy - 4
            if 2 <= zy_above <= 97 and 2 <= zx <= 117:
                plan.append((zt, zx, zy_above))

            # Zone below road lane
            zy_below = sy + 5
            if 2 <= zy_below <= 97 and 2 <= zx <= 117:
                # Different type below
                zone_type_idx2 = (i + j + 1) % 3
                if zone_type_idx2 == 0:
                    zt2 = Tool.RESIDENTIAL
                elif zone_type_idx2 == 1:
                    zt2 = Tool.COMMERCIAL
                else:
                    zt2 = Tool.INDUSTRIAL
                plan.append((zt2, zx, zy_below))

    # Add extra residential clusters near power plants for quick growth
    for px in plant_xs:
        # Residential cluster to the right of each plant
        for dy in [-6, -3, 0, 3, 6]:
            zy = strip_ys[1] + dy
            if 2 <= zy <= 97 and px + 6 <= 117:
                plan.append((Tool.RESIDENTIAL, px + 6, zy))
            if 2 <= zy <= 97 and px + 6 <= 117:
                plan.append((Tool.COMMERCIAL, px + 9, zy))

    # Vertical roads alongside zone columns to ensure road access
    for zx in zone_xs:
        # Small vertical road segment near each zone column
        for sy in strip_ys:
            for dy in range(-6, 7):
                if 0 <= sy + dy <= 99:
                    plan.append((Tool.ROAD, zx - 1, sy + dy))

    # Re-place coal plants (they might have been bulldozed by roads/wires)
    for px in plant_xs:
        plan.append((Tool.COALPOWER, px, strip_ys[0] - 3))
        plan.append((Tool.COALPOWER, px, strip_ys[1] - 3))
        plan.append((Tool.COALPOWER, px, strip_ys[2] + 3))
        plan.append((Tool.COALPOWER, px, strip_ys[3] + 3))

    return plan


