def build_plan():
    plan = []

    cy = WORLD_H // 2  # 50

    # Helper: add a cluster with wire spine, road spine, zones on both sides
    def add_cluster(wx, zones_left_type, zones_right_type, coal_side='left'):
        # Coal plant adjacent to wire spine
        if coal_side == 'left':
            plan.append((Tool.COALPOWER, wx - 2, cy))
        else:
            plan.append((Tool.COALPOWER, wx + 2, cy))

        # Wire spine at wx, road at wx+1
        for dy in range(-12, 13):
            yy = cy + dy
            if 0 <= yy < WORLD_H:
                plan.append((Tool.WIRE, wx, yy))
                plan.append((Tool.ROAD, wx + 1, yy))

        # Extra wire column for right zones
        for dy in range(-12, 13):
            yy = cy + dy
            if 0 <= yy < WORLD_H:
                plan.append((Tool.WIRE, wx + 3, yy))
                plan.append((Tool.ROAD, wx + 2, yy))

        # Left zones (centered at wx-3)
        for dy in range(-12, 13, 3):
            yy = cy + dy
            if 2 <= yy <= 97:
                plan.append((zones_left_type, wx - 3, yy))

        # Right zones (centered at wx+4)
        for dy in range(-12, 13, 3):
            yy = cy + dy
            if 2 <= yy <= 97:
                plan.append((zones_right_type, wx + 4, yy))

    # === THREE MAIN CLUSTERS ===
    # Left cluster: x=22, residential left, commercial right
    add_cluster(22, Tool.RESIDENTIAL, Tool.COMMERCIAL, coal_side='left')

    # Center cluster: x=60, residential left, commercial right  
    add_cluster(60, Tool.RESIDENTIAL, Tool.COMMERCIAL, coal_side='left')

    # Right cluster: x=98, residential left, industrial right
    # Coal on left side of wire spine
    plan.append((Tool.COALPOWER, 96, cy))
    wx = 98
    for dy in range(-12, 13):
        yy = cy + dy
        if 0 <= yy < WORLD_H:
            plan.append((Tool.WIRE, wx, yy))
            plan.append((Tool.ROAD, wx + 1, yy))
    for dy in range(-12, 13):
        yy = cy + dy
        if 0 <= yy < WORLD_H:
            plan.append((Tool.WIRE, wx - 2, yy))
            plan.append((Tool.ROAD, wx - 1, yy))
    for dy in range(-12, 13, 3):
        yy = cy + dy
        if 2 <= yy <= 97:
            plan.append((Tool.RESIDENTIAL, wx - 5, yy))
    for dy in range(-12, 13, 3):
        yy = cy + dy
        xx = min(wx + 4, WORLD_W - 4)
        if 2 <= yy <= 97:
            plan.append((Tool.INDUSTRIAL, xx, yy))

    # === CONNECT CLUSTERS with horizontal roads and wires ===
    # Left to center
    for x in range(27, 58):
        plan.append((Tool.ROAD, x, cy))
        plan.append((Tool.WIRE, x, cy - 1))
    # Center to right
    for x in range(65, 96):
        plan.append((Tool.ROAD, x, cy))
        plan.append((Tool.WIRE, x, cy - 1))

    # === UPPER CLUSTER at center-x, above main clusters ===
    uy = cy - 24
    if uy >= 4:
        plan.append((Tool.COALPOWER, 58, uy))
        for dy in range(-8, 9):
            yy = uy + dy
            if 0 <= yy < WORLD_H:
                plan.append((Tool.WIRE, 60, yy))
                plan.append((Tool.ROAD, 61, yy))
                plan.append((Tool.WIRE, 63, yy))
                plan.append((Tool.ROAD, 62, yy))
        for dy in range(-6, 7, 3):
            yy = uy + dy
            if 2 <= yy <= 97:
                plan.append((Tool.RESIDENTIAL, 57, yy))
                plan.append((Tool.COMMERCIAL, 64, yy))
        # Connect upper to center cluster
        for y in range(uy + 9, cy - 13):
            if 0 <= y < WORLD_H:
                plan.append((Tool.WIRE, 60, y))
                plan.append((Tool.ROAD, 61, y))

    # === LOWER CLUSTER at center-x, below main clusters ===
    ly2 = cy + 24
    if ly2 <= 95:
        plan.append((Tool.COALPOWER, 58, ly2))
        for dy in range(-8, 9):
            yy = ly2 + dy
            if 0 <= yy < WORLD_H:
                plan.append((Tool.WIRE, 60, yy))
                plan.append((Tool.ROAD, 61, yy))
                plan.append((Tool.WIRE, 63, yy))
                plan.append((Tool.ROAD, 62, yy))
        for dy in range(-6, 7, 3):
            yy = ly2 + dy
            if 2 <= yy <= 97:
                plan.append((Tool.RESIDENTIAL, 57, yy))
                plan.append((Tool.INDUSTRIAL, 64, yy))
        # Connect lower to center cluster
        for y in range(cy + 14, ly2 - 8):
            if 0 <= y < WORLD_H:
                plan.append((Tool.WIRE, 60, y))
                plan.append((Tool.ROAD, 61, y))

    # === UPPER LEFT CLUSTER ===
    luy = cy - 22
    if luy >= 4:
        plan.append((Tool.COALPOWER, 20, luy))
        for dy in range(-7, 8):
            yy = luy + dy
            if 0 <= yy < WORLD_H:
                plan.append((Tool.WIRE, 22, yy))
                plan.append((Tool.ROAD, 23, yy))
                plan.append((Tool.WIRE, 25, yy))
                plan.append((Tool.ROAD, 24, yy))
        for dy in range(-6, 7, 3):
            yy = luy + dy
            if 2 <= yy <= 97:
                plan.append((Tool.RESIDENTIAL, 19, yy))
                plan.append((Tool.COMMERCIAL, 26, yy))
        # Connect to left main cluster
        for y in range(luy + 8, cy - 13):
            if 0 <= y < WORLD_H:
                plan.append((Tool.WIRE, 22, y))
                plan.append((Tool.ROAD, 23, y))

    # === Services: fire and police stations ===
    plan.append((Tool.FIRESTATION, 10, cy - 10))
    plan.append((Tool.POLICESTATION, 10, cy + 10))
    plan.append((Tool.FIRESTATION, 50, cy - 10))
    plan.append((Tool.POLICESTATION, 50, cy + 10))
    plan.append((Tool.FIRESTATION, 80, cy - 10))
    plan.append((Tool.POLICESTATION, 80, cy + 10))

    return plan


