def build_plan():
    plan = []

    # === Central power hub ===
    # Place coal plant at center-left area
    px, py = 20, 50
    plan.append((Tool.COALPOWER, px, py))

    # Horizontal wire spine connecting left to right
    for x in range(px + 2, 100):
        plan.append((Tool.WIRE, x, py))

    # Second coal plant on right side for extra power
    px2, py2 = 90, 50
    plan.append((Tool.COALPOWER, px2, py2))
    # Wire from right plant leftward (already covered by spine mostly)

    # === Horizontal road just below wire spine ===
    for x in range(10, 105):
        plan.append((Tool.ROAD, x, py + 2))

    # === Vertical roads to create grid ===
    for x in range(12, 105, 9):
        for y in range(py - 15, py + 20):
            plan.append((Tool.ROAD, x, y))

    # === Residential zones - top rows ===
    # Place residential zones above the road
    for col_x in range(15, 100, 9):
        for row_y in range(py - 14, py - 1, 4):
            plan.append((Tool.RESIDENTIAL, col_x, row_y))

    # === Commercial zones - bottom rows ===
    for col_x in range(15, 100, 9):
        for row_y in range(py + 5, py + 18, 4):
            plan.append((Tool.COMMERCIAL, col_x, row_y))

    # === Industrial zones - far right column ===
    for row_y in range(py - 12, py + 18, 4):
        plan.append((Tool.INDUSTRIAL, 98, row_y))

    # === Additional vertical wire columns to power zones ===
    for col_x in range(15, 100, 9):
        for y in range(py - 15, py + 20):
            plan.append((Tool.WIRE, col_x - 1, y))

    # === Second horizontal road above zones ===
    for x in range(10, 105):
        plan.append((Tool.ROAD, x, py - 2))

    # === Third horizontal road below zones ===
    for x in range(10, 105):
        plan.append((Tool.ROAD, x, py + 15))

    # === More residential density - add a northern cluster ===
    # Northern neighborhood centered at y=25
    cy_n = 25
    plan.append((Tool.COALPOWER, 55, cy_n))
    for x in range(30, 85):
        plan.append((Tool.WIRE, x, cy_n))
    for x in range(30, 85):
        plan.append((Tool.ROAD, x, cy_n + 2))
    for x in range(30, 85):
        plan.append((Tool.ROAD, x, cy_n - 2))
    # Vertical roads
    for x in range(33, 85, 9):
        for y in range(cy_n - 8, cy_n + 8):
            plan.append((Tool.ROAD, x, y))
    # Residential above
    for col_x in range(36, 82, 9):
        for row_y in range(cy_n - 7, cy_n, 4):
            plan.append((Tool.RESIDENTIAL, col_x, row_y))
    # Commercial below
    for col_x in range(36, 82, 9):
        for row_y in range(cy_n + 3, cy_n + 8, 4):
            plan.append((Tool.COMMERCIAL, col_x, row_y))
    # Wire columns for northern cluster
    for col_x in range(36, 82, 9):
        for y in range(cy_n - 8, cy_n + 9):
            plan.append((Tool.WIRE, col_x - 1, y))

    # === Southern industrial cluster ===
    cy_s = 75
    plan.append((Tool.COALPOWER, 55, cy_s))
    for x in range(30, 85):
        plan.append((Tool.WIRE, x, cy_s))
    for x in range(30, 85):
        plan.append((Tool.ROAD, x, cy_s + 2))
    for x in range(30, 85):
        plan.append((Tool.ROAD, x, cy_s - 2))
    for col_x in range(33, 82, 6):
        for row_y in range(cy_s - 6, cy_s + 8, 4):
            plan.append((Tool.INDUSTRIAL, col_x, row_y))
    # Wire for southern cluster
    for col_x in range(33, 82, 6):
        for y in range(cy_s - 7, cy_s + 9):
            plan.append((Tool.WIRE, col_x - 1, y))

    return plan


