def build_plan():
    plan = []

    # Strategy: Two compact neighborhoods (from Parent A's success)
    # but with better power connectivity and more zones

    # === Neighborhood 1: upper-left ===
    cx1, cy1 = 30, 30

    # Coal plant - placed first, connected via wire
    plan.append((Tool.COALPOWER, cx1, cy1))

    # Horizontal wire from plant rightward to spine
    for dx in range(0, 6):
        plan.append((Tool.WIRE, cx1 + dx, cy1))

    # Vertical wire spine at cx1+5
    spine1_x = cx1 + 5
    for dy in range(-10, 11):
        plan.append((Tool.WIRE, spine1_x, cy1 + dy))

    # Road spine at cx1+6 (adjacent to wire, zones get road access)
    road1_x = cx1 + 6
    for dy in range(-10, 11):
        plan.append((Tool.ROAD, road1_x, cy1 + dy))

    # Horizontal roads at zone rows to improve access
    for dy in range(-9, 11, 3):
        for dx in range(-4, 8):
            plan.append((Tool.ROAD, cx1 + dx, cy1 + dy))

    # Residential zones left of spine
    for dy in range(-9, 10, 3):
        if -10 <= dy <= 10:
            plan.append((Tool.RESIDENTIAL, spine1_x - 3, cy1 + dy))

    # Commercial and industrial right of road
    for i, dy in enumerate(range(-9, 10, 3)):
        if i % 2 == 0:
            plan.append((Tool.COMMERCIAL, road1_x + 3, cy1 + dy))
        else:
            plan.append((Tool.INDUSTRIAL, road1_x + 3, cy1 + dy))

    # Re-place coal plant to ensure it wasn't bulldozed
    plan.append((Tool.COALPOWER, cx1, cy1))

    # === Neighborhood 2: lower-right ===
    cx2, cy2 = 80, 70

    # Coal plant
    plan.append((Tool.COALPOWER, cx2, cy2))

    # Horizontal wire from plant rightward to spine
    for dx in range(0, 6):
        plan.append((Tool.WIRE, cx2 + dx, cy2))

    # Vertical wire spine
    spine2_x = cx2 + 5
    for dy in range(-10, 11):
        plan.append((Tool.WIRE, spine2_x, cy2 + dy))

    # Road spine
    road2_x = cx2 + 6
    for dy in range(-10, 11):
        plan.append((Tool.ROAD, road2_x, cy2 + dy))

    # Horizontal roads at zone rows
    for dy in range(-9, 11, 3):
        for dx in range(-4, 8):
            plan.append((Tool.ROAD, cx2 + dx, cy2 + dy))

    # Residential zones left of spine
    for dy in range(-9, 10, 3):
        plan.append((Tool.RESIDENTIAL, spine2_x - 3, cy2 + dy))

    # Commercial and industrial right of road
    for i, dy in enumerate(range(-9, 10, 3)):
        if i % 2 == 0:
            plan.append((Tool.COMMERCIAL, road2_x + 3, cy2 + dy))
        else:
            plan.append((Tool.INDUSTRIAL, road2_x + 3, cy2 + dy))

    # Re-place coal plant
    plan.append((Tool.COALPOWER, cx2, cy2))

    # === Neighborhood 3: middle area ===
    cx3, cy3 = 55, 50

    plan.append((Tool.COALPOWER, cx3, cy3))

    for dx in range(0, 6):
        plan.append((Tool.WIRE, cx3 + dx, cy3))

    spine3_x = cx3 + 5
    for dy in range(-8, 9):
        plan.append((Tool.WIRE, spine3_x, cy3 + dy))

    road3_x = cx3 + 6
    for dy in range(-8, 9):
        plan.append((Tool.ROAD, road3_x, cy3 + dy))

    for dy in range(-6, 7, 3):
        for dx in range(-4, 8):
            plan.append((Tool.ROAD, cx3 + dx, cy3 + dy))

    for dy in range(-6, 7, 3):
        plan.append((Tool.RESIDENTIAL, spine3_x - 3, cy3 + dy))

    for i, dy in enumerate(range(-6, 7, 3)):
        if i % 2 == 0:
            plan.append((Tool.COMMERCIAL, road3_x + 3, cy3 + dy))
        else:
            plan.append((Tool.INDUSTRIAL, road3_x + 3, cy3 + dy))

    plan.append((Tool.COALPOWER, cx3, cy3))

    # === Connecting road between neighborhoods ===
    # Horizontal road connecting neighborhoods at mid-height
    for x in range(35, 86):
        plan.append((Tool.ROAD, x, 50))

    # Additional residential zones near each plant for quick growth
    for cx, cy in [(cx1, cy1), (cx2, cy2), (cx3, cy3)]:
        for dy in [-3, 0, 3]:
            plan.append((Tool.RESIDENTIAL, cx - 3, cy + dy))

