        for x in range(5, WORLD_W - 5):
            plan.append((Tool.ROAD, x, sy + 1))

    # Vertical roads to connect strips and serve zones
    # Place vertical roads every 6 columns
    vert_road_xs = list(range(8, WORLD_W - 5, 6))
