            py = sy - 2
            if 1 <= py <= 98 and 1 <= cx <= 118:
                plan.append((Tool.COALPOWER, cx, py))
                plant_positions.append((cx, py))

    # Re-lay wire from each plant to the wire backbone to ensure connectivity
    for cx, py in plant_positions:
        # Wire from plant bottom to backbone
        for y in range(py + 2, py + 3):
            if 0 <= y <= 99:
