    def add_neighborhood(cx, cy, half=10, plant_left=True):
        """Build a self-contained neighborhood centered at (cx, cy)"""
        # Coal plant placement
        if plant_left:
            px, py = cx - 10, cy
        else:
            px, py = cx + 10, cy

        # Clamp plant position
        px = max(2, min(WORLD_W - 4, px))
        py = max(2, min(WORLD_H - 4, py))
