        # Wire from plant to vertical spine at cx
        if plant_left:
            for x in range(px + 2, cx + 1):
                plan.append((Tool.WIRE, x, cy))
        else:
            for x in range(cx, px - 1):
                plan.append((Tool.WIRE, x, cy))

        # Vertical wire spine at cx
        for dy in range(-half - 1, half + 2):
            yy = cy + dy
            if 0 <= yy <= WORLD_H - 1:
                plan.append((Tool.WIRE, cx, yy))

        # Vertical road spine at cx+1
        for dy in range(-half - 1, half + 2):
            yy = cy + dy
