                plan.append((Tool.ROAD, cx + 1, yy))

        # Horizontal roads: center, top, bottom
        for dx in range(-8, 9):
            xx = cx + dx
            if 0 <= xx <= WORLD_W - 1:
                plan.append((Tool.ROAD, xx, cy))
                if 0 <= cy - half <= WORLD_H - 1:
                    plan.append((Tool.ROAD, xx, cy - half))
                if 0 <= cy + half <= WORLD_H - 1:
                    plan.append((Tool.ROAD, xx, cy + half))

        # Left vertical road (for left zones)
        for dy in range(-half, half + 1):
            yy = cy + dy
            if 0 <= yy <= WORLD_H - 1:
                plan.append((Tool.ROAD, cx - 7, yy))

        # Place zones: left column at cx-4, right column at cx+4
        row_offsets = list(range(-half + 2, half - 1, 3))
        for i, dy in enumerate(row_offsets):
            zy = cy + dy
            if 3 <= zy <= WORLD_H - 4:
                # Left zones
                zx_l = cx - 4
                if 3 <= zx_l <= WORLD_W - 4:
